package com.sari.subtitle

import android.content.Intent
import android.net.Uri
import android.os.Bundle
import android.view.View
import android.widget.TextView
import android.widget.ArrayAdapter
import android.widget.Toast
import androidx.appcompat.app.AppCompatActivity
import androidx.lifecycle.lifecycleScope
import com.google.android.material.appbar.MaterialToolbar
import com.google.android.material.button.MaterialButton
import com.google.android.material.materialswitch.MaterialSwitch
import com.google.android.material.slider.Slider
import com.google.android.material.textfield.TextInputEditText
import com.google.android.material.textfield.MaterialAutoCompleteTextView
import com.google.android.material.textfield.TextInputLayout
import kotlinx.coroutines.launch

abstract class SettingsSubpageActivity : AppCompatActivity() {
    protected abstract val page: String
    private lateinit var secret: TextInputEditText
    private lateinit var url: TextInputEditText
    private lateinit var model: TextInputEditText
    private lateinit var alternates: TextInputEditText
    private lateinit var translationModel: TextInputEditText
    private lateinit var glossary: TextInputEditText
    private lateinit var translationKey: TextInputEditText
    private lateinit var email: TextInputEditText
    private lateinit var contextPrompt: TextInputEditText
    private lateinit var contextAware: MaterialSwitch
    private lateinit var memory: MaterialSwitch
    private lateinit var smart: MaterialSwitch
    private lateinit var retry: MaterialSwitch
    private lateinit var compare: MaterialSwitch
    private lateinit var streaming: MaterialSwitch
    private lateinit var quota: MaterialSwitch
    private lateinit var benchmark: MaterialSwitch
    private lateinit var breaker: MaterialSwitch
    private lateinit var adaptive: MaterialSwitch
    private lateinit var font: Slider
    private lateinit var opacity: Slider
    private lateinit var action: MaterialButton
    private lateinit var providerChoice: MaterialAutoCompleteTextView
    private lateinit var positionChoice: MaterialAutoCompleteTextView
    private fun id(id: Int) = findViewById<View>(id)
    private fun show(vararg ids: Int) { val all = listOf(R.id.providerLayout,R.id.positionLayout,R.id.fieldSecretLayout,R.id.translationKeyLayout,R.id.emailLayout,R.id.contextPromptLayout,R.id.fieldUrlLayout,R.id.fieldModelLayout,R.id.fieldTranslationModelLayout,R.id.fieldAlternatesLayout,R.id.fieldGlossaryLayout,R.id.fontSizeSlider,R.id.fontSizeLabel,R.id.opacitySlider,R.id.opacityLabel,R.id.contextAwareSwitch,R.id.translationMemorySwitch,R.id.smartRoutingSwitch,R.id.qualityRetrySwitch,R.id.compareCandidatesSwitch,R.id.streamingSwitch,R.id.quotaSwitch,R.id.benchmarkSwitch,R.id.circuitBreakerSwitch,R.id.adaptiveRoutingSwitch,R.id.subpageActionButton); all.forEach { id(it).visibility = if (it in ids) View.VISIBLE else View.GONE } }
    override fun onCreate(savedInstanceState: Bundle?) { super.onCreate(savedInstanceState); setContentView(R.layout.activity_settings_subpage)
        val title = findViewById<MaterialToolbar>(R.id.subpageToolbar); title.title = titleForPage(); title.setNavigationOnClickListener { finish() }
        findViewById<TextView>(R.id.subpageDescription).text = descriptionForPage()
        secret=findViewById(R.id.fieldSecret); translationKey=findViewById(R.id.translationKeyField); email=findViewById(R.id.emailField); contextPrompt=findViewById(R.id.contextPromptField); url=findViewById(R.id.fieldUrl); model=findViewById(R.id.fieldModel); translationModel=findViewById(R.id.fieldTranslationModel); alternates=findViewById(R.id.fieldAlternates); glossary=findViewById(R.id.fieldGlossary)
        contextAware=findViewById(R.id.contextAwareSwitch); memory=findViewById(R.id.translationMemorySwitch); smart=findViewById(R.id.smartRoutingSwitch); retry=findViewById(R.id.qualityRetrySwitch); compare=findViewById(R.id.compareCandidatesSwitch); streaming=findViewById(R.id.streamingSwitch); quota=findViewById(R.id.quotaSwitch); benchmark=findViewById(R.id.benchmarkSwitch); breaker=findViewById(R.id.circuitBreakerSwitch); adaptive=findViewById(R.id.adaptiveRoutingSwitch)
        providerChoice=findViewById(R.id.providerChoice); positionChoice=findViewById(R.id.positionChoice); providerChoice.setAdapter(ArrayAdapter(this, android.R.layout.simple_dropdown_item_1line, listOf("Groq", "Google Cloud Translation", "MyMemory", "OmniRoute — Multi-Provider", "OpenAI"))); positionChoice.setAdapter(ArrayAdapter(this, android.R.layout.simple_dropdown_item_1line, listOf("أعلى", "وسط", "أسفل"))); providerChoice.setOnClickListener { providerChoice.showDropDown() }; positionChoice.setOnClickListener { positionChoice.showDropDown() }; font=findViewById(R.id.fontSizeSlider); opacity=findViewById(R.id.opacitySlider); action=findViewById(R.id.subpageActionButton)
        configurePage(); font.addOnChangeListener { _, v, _ -> findViewById<TextView>(R.id.fontSizeLabel).text = "حجم الخط: ${v.toInt()} sp" }; opacity.addOnChangeListener { _, v, _ -> findViewById<TextView>(R.id.opacityLabel).text = "الشفافية: ${v.toInt()}%" }
        action.setOnClickListener { onAction() }; findViewById<MaterialButton>(R.id.subpageSaveButton).setOnClickListener { savePage() }
        lifecycleScope.launch { val s=SettingsRepository(this@SettingsSubpageActivity).load(); providerChoice.setText(listOf("Groq", "Google Cloud Translation", "MyMemory", "OmniRoute — Multi-Provider", "OpenAI")[s.provider.coerceIn(0,4)], false); positionChoice.setText(when(s.subtitlePosition){"top"->"أعلى";"center"->"وسط";else->"أسفل"}, false); secret.setText(if(page=="keys") s.speechKey else s.omniRouteKey); translationKey.setText(s.translationKey); email.setText(s.myMemoryEmail); contextPrompt.setText(s.contextPrompt); url.setText(if(page=="languages") s.speechLanguage else s.omniRouteBaseUrl); model.setText(when(page) { "languages" -> s.sourceLanguage; "quality" -> listOf("Fast","Balanced","Human Quality")[s.translationQuality.coerceIn(0,2)]; else -> s.omniRouteSttModels }); translationModel.setText(s.omniRouteTranslationModel); alternates.setText(if(page=="languages") s.targetLanguage else s.omniRouteTranslationModels); glossary.setText(s.glossary); contextAware.isChecked=s.contextAwareTranslation; memory.isChecked=s.translationMemoryEnabled; smart.isChecked=s.smartRoutingEnabled; retry.isChecked=s.qualityRetryEnabled; compare.isChecked=s.compareCandidatesEnabled; streaming.isChecked=s.streamingOrchestrationEnabled; quota.isChecked=s.quotaMonitoringEnabled; benchmark.isChecked=s.providerBenchmarkEnabled; breaker.isChecked=s.circuitBreakerEnabled; adaptive.isChecked=s.adaptiveRoutingEnabled; font.value=s.fontSize.coerceIn(12,48).toFloat(); opacity.value=s.opacity.coerceIn(0,100).toFloat(); findViewById<TextView>(R.id.fontSizeLabel).text="حجم الخط: ${s.fontSize} sp"; findViewById<TextView>(R.id.opacityLabel).text="الشفافية: ${s.opacity}%" }
    }
    private fun configurePage() { when(page) {
        "keys" -> { show(R.id.providerLayout,R.id.fieldSecretLayout,R.id.translationKeyLayout,R.id.emailLayout); findViewById<TextInputLayout>(R.id.fieldSecretLayout).hint="Groq API Key"; findViewById<TextInputLayout>(R.id.translationKeyLayout).hint="Translation API Key (اختياري)"; findViewById<TextInputLayout>(R.id.emailLayout).hint="MyMemory Email (اختياري)"; findViewById<com.google.android.material.textfield.TextInputEditText>(R.id.fieldSecret).inputType= android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD }
        "languages" -> { show(R.id.fieldUrlLayout,R.id.fieldModelLayout,R.id.fieldAlternatesLayout); findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldUrlLayout).hint="لغة التعرف على الكلام (auto/ar/en)"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldModelLayout).hint="لغة النص الأصلي (auto/ar/en)"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldAlternatesLayout).hint="لغة الترجمة (ar/en/...)" }
        "appearance" -> { show(R.id.fontSizeSlider,R.id.fontSizeLabel,R.id.opacitySlider,R.id.opacityLabel,R.id.positionLayout); findViewById<TextView>(R.id.fontSizeLabel).text="حجم الخط"; findViewById<TextView>(R.id.opacityLabel).text="الشفافية" }
        "quality" -> { show(R.id.fieldModelLayout); findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldModelLayout).hint="Fast / Balanced / Human Quality" }
        "context" -> { show(R.id.contextAwareSwitch,R.id.translationMemorySwitch,R.id.contextPromptLayout,R.id.fieldGlossaryLayout); findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldGlossaryLayout).hint="قاموس المصطلحات" }
        "omniroute" -> { show(R.id.fieldSecretLayout,R.id.fieldUrlLayout,R.id.fieldModelLayout,R.id.fieldTranslationModelLayout,R.id.fieldAlternatesLayout,R.id.subpageActionButton); findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldSecretLayout).hint="OmniRoute API Key"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldUrlLayout).hint="Base URL (مثال: http://127.0.0.1:20128/v1)"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldModelLayout).hint="STT Models"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldTranslationModelLayout).hint="Translation Model الأساسي"; findViewById<com.google.android.material.textfield.TextInputLayout>(R.id.fieldAlternatesLayout).hint="Translation models البديلة"; action.text="اختبار الاتصال" }
        "orchestration" -> show(R.id.smartRoutingSwitch,R.id.qualityRetrySwitch,R.id.compareCandidatesSwitch,R.id.streamingSwitch,R.id.quotaSwitch,R.id.benchmarkSwitch,R.id.circuitBreakerSwitch,R.id.adaptiveRoutingSwitch,R.id.subpageActionButton).also { action.text="فتح لوحة المزودين" }
        "about" -> { show(); findViewById<MaterialButton>(R.id.subpageSaveButton).visibility=View.GONE; findViewById<TextView>(R.id.subpageDescription).text="Sari Subtitle\nالإصدار ${BuildConfig.VERSION_NAME}\nترجمة صوتية فورية مع نافذة ترجمة عائمة." }
        else -> show()
    } }
    private fun titleForPage() = when(page) { "keys"->"مفاتيح API"; "languages"->"اللغات"; "appearance"->"المظهر"; "quality"->"جودة الترجمة"; "context"->"الترجمة السياقية"; "omniroute"->"OmniRoute"; "orchestration"->"AI Orchestration"; "about"->"حول التطبيق"; else->"الإعدادات" }
    private fun descriptionForPage() = when(page) { "keys"->"اترك حقل المفتاح فارغًا للاحتفاظ بالمفتاح المحفوظ. التخزين مشفر عبر SettingsRepository."; "languages"->"استخدم رموز لغة يدعمها المزود المحدد. auto متاح للتعرف على الكلام عندما يدعمه المزود."; "appearance"->"تُحفظ قيم الحجم والشفافية. تطبيقهما على نافذة Overlay يحتاج تحققًا منفصلًا من الخدمة."; "quality"->"Human Quality يحاول مراجعة الترجمة ولا يضمن جودة بشرية."; "context"->"تؤثر هذه الخيارات على ترجمة السياق وذاكرة النصوص والقاموس."; "omniroute"->"استخدم عنوان API متوافقًا مع OpenAI؛ على الهاتف نفسه يمكن تجربة http://127.0.0.1:20128/v1."; "orchestration"->"تتحكم هذه المفاتيح بخيارات التوجيه والتجربة وإعادة المحاولة."; else->"إعدادات Sari Subtitle" }
    private fun savePage() { lifecycleScope.launch { try { val r=SettingsRepository(this@SettingsSubpageActivity); val s=r.load(); val target=if(page=="languages") alternates.text?.toString()?.trim().orEmpty().ifBlank { s.targetLanguage } else s.targetLanguage; val source=if(page=="languages") model.text?.toString()?.trim().orEmpty().ifBlank { s.sourceLanguage } else s.sourceLanguage; val speech=if(page=="languages") url.text?.toString()?.trim().orEmpty().ifBlank { s.speechLanguage } else s.speechLanguage; if(page=="languages") { val languagePattern=Regex("(?i)^(auto|[a-z]{2,3}(-[a-z0-9]{2,8})*)$"); require(languagePattern.matches(speech)) { "رمز لغة التعرف غير صالح. استخدم مثل auto أو en أو ar." }; require(languagePattern.matches(source)) { "رمز لغة النص الأصلي غير صالح. استخدم مثل auto أو en أو ar." }; require(languagePattern.matches(target) && !target.equals("auto", ignoreCase=true)) { "لغة الترجمة يجب أن تكون رمز لغة محددًا مثل ar أو en، وليست auto." } }; val quality=if(page=="quality") when(model.text?.toString()?.trim()?.lowercase()) { "fast"->SettingsRepository.QUALITY_FAST; "balanced"->SettingsRepository.QUALITY_BALANCED; "human quality","human"->SettingsRepository.QUALITY_HUMAN; else->s.translationQuality } else s.translationQuality; val base=if(page=="omniroute") url.text?.toString()?.trim().orEmpty() else s.omniRouteBaseUrl; if(page=="omniroute" && base.isNotBlank()) { val parsed=Uri.parse(base); require(parsed.scheme in listOf("http","https") && !parsed.host.isNullOrBlank()) { "أدخل Base URL صحيحًا يبدأ بـ http:// أو https://" } }; r.save(provider=if(page=="keys") listOf("Groq", "Google Cloud Translation", "MyMemory", "OmniRoute — Multi-Provider", "OpenAI").indexOf(providerChoice.text?.toString()).coerceIn(0,4) else s.provider, speechKey=if(page=="keys") secret.text?.toString()?.trim().orEmpty().ifBlank { s.speechKey } else s.speechKey, translationKey=if(page=="keys") translationKey.text?.toString()?.trim().orEmpty().ifBlank { s.translationKey } else s.translationKey, source=source, target=target, font=if(page=="appearance") font.value.toInt() else s.fontSize, opacity=if(page=="appearance") opacity.value.toInt() else s.opacity, email=if(page=="keys") email.text?.toString()?.trim().orEmpty() else s.myMemoryEmail, speechLanguage=speech, contextAwareTranslation=if(page=="context") contextAware.isChecked else s.contextAwareTranslation, translationMemoryEnabled=if(page=="context") memory.isChecked else s.translationMemoryEnabled, glossary=if(page=="context") glossary.text?.toString().orEmpty() else s.glossary, contextPrompt=if(page=="context") contextPrompt.text?.toString().orEmpty() else s.contextPrompt, subtitlePosition=if(page=="appearance") when(positionChoice.text?.toString()) { "أعلى"->"top"; "وسط"->"center"; else->"bottom" } else s.subtitlePosition, translationQuality=quality, omniRouteBaseUrl=base, omniRouteKey=if(page=="omniroute") secret.text?.toString()?.trim().orEmpty().ifBlank { s.omniRouteKey } else s.omniRouteKey, omniRouteSttModels=if(page=="omniroute") model.text?.toString()?.trim().orEmpty().ifBlank { s.omniRouteSttModels } else s.omniRouteSttModels, omniRouteTranslationModel=if(page=="omniroute") translationModel.text?.toString()?.trim().orEmpty().ifBlank { s.omniRouteTranslationModel } else s.omniRouteTranslationModel, omniRouteTranslationModels=if(page=="omniroute") alternates.text?.toString()?.trim().orEmpty().ifBlank { s.omniRouteTranslationModels } else s.omniRouteTranslationModels, smartRoutingEnabled=if(page=="orchestration") smart.isChecked else s.smartRoutingEnabled, qualityRetryEnabled=if(page=="orchestration") retry.isChecked else s.qualityRetryEnabled, compareCandidatesEnabled=if(page=="orchestration") compare.isChecked else s.compareCandidatesEnabled, streamingOrchestrationEnabled=if(page=="orchestration") streaming.isChecked else s.streamingOrchestrationEnabled, quotaMonitoringEnabled=if(page=="orchestration") quota.isChecked else s.quotaMonitoringEnabled, providerBenchmarkEnabled=if(page=="orchestration") benchmark.isChecked else s.providerBenchmarkEnabled, circuitBreakerEnabled=if(page=="orchestration") breaker.isChecked else s.circuitBreakerEnabled, adaptiveRoutingEnabled=if(page=="orchestration") adaptive.isChecked else s.adaptiveRoutingEnabled, benchmarkIntervalMs=s.benchmarkIntervalMs, hedgedFailoverEnabled=s.hedgedFailoverEnabled, hedgeDelayMs=s.hedgeDelayMs); Toast.makeText(this@SettingsSubpageActivity,"تم حفظ الإعدادات",Toast.LENGTH_SHORT).show() } catch(e:Exception) { Toast.makeText(this@SettingsSubpageActivity,"تعذر الحفظ: ${e.message ?: "خطأ غير معروف"}",Toast.LENGTH_LONG).show() } } }
    private fun onAction() { if(page=="keys") { startActivity(Intent(Intent.ACTION_VIEW, Uri.parse("https://console.groq.com/keys"))) } else if(page=="orchestration") startActivity(Intent(this,ProviderDashboardActivity::class.java)) else if(page=="omniroute") { val base=url.text?.toString()?.trim().orEmpty().trimEnd('/'); if(base.isBlank()) { Toast.makeText(this,"أدخل Base URL أولاً",Toast.LENGTH_LONG).show(); return }; lifecycleScope.launch { try { val request=okhttp3.Request.Builder().url("$base/models").get().apply { secret.text?.toString()?.trim()?.takeIf { it.isNotBlank() }?.let { header("Authorization","Bearer $it") } }.build(); val result= kotlinx.coroutines.withContext(kotlinx.coroutines.Dispatchers.IO) { okhttp3.OkHttpClient.Builder().connectTimeout(15,java.util.concurrent.TimeUnit.SECONDS).readTimeout(20,java.util.concurrent.TimeUnit.SECONDS).build().newCall(request).execute().use { "HTTP ${it.code}" } }; Toast.makeText(this@SettingsSubpageActivity,"نتيجة اختبار OmniRoute: $result",Toast.LENGTH_LONG).show() } catch(e:Exception) { Toast.makeText(this@SettingsSubpageActivity,"فشل الاتصال: ${e.message}",Toast.LENGTH_LONG).show() } } } }
}
